def _as_float(v):
    if isinstance(v, torch.Tensor):
        return float(v.item())
    return float(v)


def _prep3d(t, batch_shape, d0, d1):
    """Zero-copy bring t to a 3-D (B, d0, d1) view with batch dims broadcast."""
    nb = len(batch_shape)
    while t.dim() < nb + 2:
        t = t.unsqueeze(0)
    want = tuple(batch_shape) + (d0, d1)
    if tuple(t.shape) != want:
        t = t.expand(want)
    if t.dim() == 2:
        t = t.unsqueeze(0)
    elif t.dim() > 3:
        B = 1
        for d in batch_shape:
            B *= d
        t = t.reshape(B, d0, d1)
    return t


